  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;rudit-Du-Savoir-(Pr&#234;tre).html&quot; title=&quot;&#201;rudit du savoir&quot;&gt;&#201;rudit du savoir&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vang&#233;liste-(Pr&#234;tre).html&quot; title=&quot;&#201;vang&#233;liste&quot;&gt;&#201;vang&#233;liste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseur-Mis&#233;ricordieux-(Pr&#234;tre).html&quot; title=&quot;Gu&#233;risseur mis&#233;ricordieux&quot;&gt;Gu&#233;risseur mis&#233;ricordieux&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Forges-(Pr&#234;tre).html&quot; title=&quot;Ma&#238;tre des forges&quot;&gt;Ma&#238;tre des forges&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#232;lerin-Varisien-(Pr&#234;tre).html&quot; title=&quot;P&#232;lerin nomade&quot;&gt;P&#232;lerin nomade&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Clandestin-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre clandestin&quot;&gt;Pr&#234;tre clandestin&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Clo&#238;tr&#233;-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre clo&#238;tr&#233;&quot;&gt;Pr&#234;tre clo&#238;tr&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Mend&#233;vien-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre crois&#233;&quot;&gt;Pr&#234;tre crois&#233;&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;ceptacle-Fi&#233;lon-(Pr&#234;tre).html&quot; title=&quot;R&#233;ceptacle fi&#233;lon&quot;&gt;R&#233;ceptacle fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Combattant-(Pr&#234;tre).html&quot; title=&quot;Saint combattant&quot;&gt;Saint combattant&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Morts-Vivants-(Pr&#234;tre).html&quot; title=&quot;Seigneur des morts-vivants&quot;&gt;Seigneur des morts-vivants&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;S&#233;paratiste-(Pr&#234;tre).html&quot; title=&quot;S&#233;paratiste&quot;&gt;S&#233;paratiste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Strat&#232;ge-Divin-(Pr&#234;tre).html&quot; title=&quot;Strat&#232;ge divin&quot;&gt;Strat&#232;ge divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;ologien-(Pr&#234;tre).html&quot; title=&quot;Th&#233;ologien&quot;&gt;Th&#233;ologien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;urge-Eccl&#233;siastique-(Pr&#234;tre).html&quot; title=&quot;Th&#233;urge eccl&#233;siastique&quot;&gt;Th&#233;urge eccl&#233;siastique&lt;/a&gt; (MCA)&lt;/li&gt;
